const rows = $input.all().map((item) => item.json || {});
const urlSet = new Set();
let minReadinessScore = 40;

for (const row of rows) {
  const raw = row.url || row.bioUrl || row.sourceUrl || row.link || '';
  if (typeof raw === 'string' && raw.trim().length > 0) {
    urlSet.add(raw.trim());
  }
  const rawScore = row.minReadinessScore ?? row.min_readiness_score;
  if (rawScore !== '' && rawScore !== null && rawScore !== undefined && String(rawScore).trim() !== '') {
    const score = Number(rawScore);
    if (Number.isFinite(score) && score >= 0 && score <= 100) {
      minReadinessScore = Math.round(score);
    }
  }
}

const urls = urlSet.size > 0
  ? Array.from(urlSet)
  : [
      'https://linktr.ee/averagefashionblogger',
      'https://linktr.ee/halleykmcg',
      'https://stan.store/stan'
    ];

return [
  {
    json: {
      urls,
      enableDeepContactFollow: true,
      onlyWithEmail: false,
      minReadinessScore,
      maxProfiles: 500,
      maxConcurrency: 3
    }
  }
];

const items = $input.all();
const results = [];

for (const item of items) {
  const d = item.json || {};
  const score = Number(d.creatorReadinessScore || 0);
  const emailType = String(d.emailType || '').toLowerCase();
  const reasons = Array.isArray(d.scoreReasons) ? d.scoreReasons : [];
  const codes = Array.isArray(d.discountCodes) ? d.discountCodes : [];

  let outreachTier = 'NURTURE';
  if (score >= 75 || emailType === 'agency' || d.hasMediaKit === true) {
    outreachTier = 'VIP_AGENCY';
  } else if (score >= 50 || d.hasBrandDeals === true || d.hasAffiliateStorefront === true) {
    outreachTier = 'DIRECT_READY';
  }

  const nameLabel = d.displayName || d.handle || d.sourceUrl;
  const emoji = outreachTier === 'VIP_AGENCY' ? ':star2:' : outreachTier === 'DIRECT_READY' ? ':handshake:' : ':seedling:';
  const scoreReasonsText = reasons.join(', ');

  const slackSummary = [
    `${emoji} *[${outreachTier}] Creator Partner Lead:* ${nameLabel} (Score: *${score}/100*)`,
    `*Platform:* ${d.platform || 'Unknown'} | *Bio:* ${d.sourceUrl || 'N/A'}`,
    `*Email:* ${d.primaryEmail} (\`${d.emailType || 'business'}\` via ${d.emailSource || 'bio'})`,
    `*Monetization:* Brand Deals=${d.hasBrandDeals ? 'Yes' : 'No'} | Affiliate=${d.hasAffiliateStorefront ? 'Yes' : 'No'} | Media Kit=${d.hasMediaKit ? 'Yes' : 'No'}`,
    `*Socials:* ${d.socialCount || 0} linked${codes.length > 0 ? ` | *Codes:* ${codes.join(', ')}` : ''}`
  ].join('\n');

  const pitchSubject = `[VIP Creator Brief] ${nameLabel} — Readiness ${score}/100 (${d.emailType || 'business'})`;
  const pitchBody = [
    `Outreach Tier: ${outreachTier}`,
    `Creator: ${nameLabel} (@${d.handle || 'unknown'})`,
    `Readiness Score: ${score}/100 (${scoreReasonsText || 'N/A'})`,
    `Contact Email: ${d.primaryEmail} (${d.emailType || 'N/A'}, source: ${d.emailSource || 'N/A'})`,
    `Bio URL: ${d.sourceUrl || 'N/A'}`,
    `Signals: Brand Deals=${d.hasBrandDeals}, Affiliate Storefront=${d.hasAffiliateStorefront}, Digital Products=${d.hasDigitalProducts}, Media Kit=${d.hasMediaKit}`,
    `Linked Social Profiles: ${d.socialCount || 0}`,
    `Enriched At: ${d.enrichedAt || 'N/A'}`
  ].join('\n');

  results.push({
    json: {
      ...d,
      outreachTier,
      scoreReasonsText,
      slackSummary,
      pitchSubject,
      pitchBody
    }
  });
}

return results;
